// Helper function for movement pattern
vec2 getFlowerPosition(float baseX, float baseY, float time) {
    float xOffset = 0.05 * sin(time * 0.5 + baseY * 2.0);
    float yOffset = 0.05 * cos(time * 0.4 + baseX * 2.0);

    return vec2(
        baseX + xOffset,
        baseY + yOffset
    );
}

// Overlapping flower
vec3 createFlower(vec2 uv, vec2 pos, float timeOffset) {
    float t = iTime * 0.5 + timeOffset;
    vec2 flowerUV = uv - pos;
    float scale = 0.15;
    flowerUV = flowerUV / scale;

    float pulseScale = 1.0 + 0.2 * sin(t * 2.0);
    vec2 p = (flowerUV - 0.5) / pulseScale;

    float len = length(p);
    float angle = atan(p.y, p.x) + t;
    float radius = 0.5 + 0.5 * sin(6.0 * angle + t);
    vec3 color = vec3(0.5 + 0.5 * sin(t), 0.5 + 0.5 * cos(t), 0.5 + 0.5 * sin(t + 1.0));
    return color * smoothstep(0.4, 0.5, radius - len);
}

vec3 createBaseFlower(vec2 uv, vec2 pos, float timeOffset) {
    float t = iTime * 0.3 + timeOffset;
    vec2 flowerUV = uv - pos;
    float scale = 0.15;
    flowerUV = flowerUV / scale;

    float pulseScale = 1.0 + 0.15 * sin(t * 3.0);
    vec2 p = (flowerUV - 0.5) / pulseScale;

    float len = length(p);
    float angle = atan(p.y, p.x) + t;
    float radius = 0.5 + 0.5 * cos(8.0 * angle + t);
    vec3 color = vec3(0.5 + 0.5 * cos(t + 2.0), 0.5 + 0.5 * sin(t + 2.0), 0.5 + 0.5 * cos(t));
    return color * smoothstep(0.3, 0.4, radius - len);
}

// Noise function
vec3 pattern3(vec2 uv) {
    float t = iTime * 0.1;
    vec2 p = uv - 0.5;
    float noise = sin(dot(p, vec2(12.9898, 78.233)) * 43758.5453 + t);
    vec3 color = vec3(0.5 + 0.5 * sin(t + 3.0), 0.5 + 0.5 * cos(t + 3.0), 0.5 + 0.5 * sin(t));
    return color * noise * 0.3;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec3 color = vec3(0.0);

    float aspectRatio = iResolution.x / iResolution.y;
    float spacing = 0.20; // Adjust this to control density

    // Calculate number of flowers needed to fill screen
    int numX = int(ceil(1.0 / spacing)) + 2; // extra columns
    int numY = int(ceil(1.0 / spacing)) + 2; // extra rows

    float startX = -spacing;
    float startY = -spacing;

    // grid of flowers
    for(int i = 0; i < numX; i++) {
        for(int j = 0; j < numY; j++) {
            float baseX = startX + float(i) * spacing;
            float baseY = startY + float(j) * spacing;
            float timeOffset = float(i) * 0.5 + float(j) * 0.3;

            vec2 flowerPos = getFlowerPosition(baseX, baseY, iTime);

            color += createFlower(uv, flowerPos, timeOffset) * 0.5;
            color += createBaseFlower(uv, flowerPos, timeOffset) * 0.5;
        }
    }

    color += pattern3(uv);

    fragColor = vec4(color, 1.0);
}
